/* JOBWAN 2.0 — เว็บแอปตัวอย่างแบบ Local-first, ไม่มี AI diagnosis */
'use strict';
const NAV=[['home','⌂','ภาพรวม'],['diary','📖','ไดอารี่ & จบวัน'],['community','♡','พื้นที่ปล่อยใจ'],['checkin','◔','เช็กใจ'],['help','✚','ค้นหาความช่วยเหลือ'],['articles','▤','บทความ'],['settings','⚙','ตั้งค่า']];
const SKEY='jobwan_v2_private';
const readState=()=>{try{return JSON.parse(localStorage.getItem(SKEY)||'{}')}catch{return {}}};
const saved=readState();
const MOODS=[{emoji:'😄',label:'ดีมาก',score:5},{emoji:'🙂',label:'โอเค',score:4},{emoji:'😮\u200d💨',label:'เหนื่อย',score:3},{emoji:'😣',label:'เครียด',score:2},{emoji:'😞',label:'ไม่ไหว',score:1}];
const now0=new Date();
const state={page:'home',demoPosts:Array.isArray(saved.demoPosts)?saved.demoPosts:[],communityTokens:Array.isArray(saved.communityTokens)?saved.communityTokens:[],diary:(saved.diary&&typeof saved.diary==='object'&&!Array.isArray(saved.diary))?saved.diary:{},released:Array.isArray(saved.released)?saved.released:[],step:0,articleId:null,online:false,posts:[],modeChecked:false,communityFilter:'all',communityTab:'public',diaryViewMode:'form',selectedDiaryDate:null,calYear:now0.getFullYear(),calMonth:now0.getMonth(),diaryReportRange:'week',memoryReveal:null,org:(saved.org&&typeof saved.org==='object')?saved.org:null,hrLoggedIn:false,hrAdminEmail:null,hrOnlySession:false,purchased:saved.purchased===true,entryTab:'individual'};
const ORG_DEPARTMENTS=[{name:'วิศวกรรม/เทคโนโลยี',size:280},{name:'ฝ่ายขาย',size:190},{name:'ปฏิบัติการ',size:230},{name:'การตลาด',size:90},{name:'การเงิน/บัญชี',size:65},{name:'ทรัพยากรบุคคล',size:35},{name:'บริการลูกค้า',size:110}];
function regenOrgScaleSim(){state.hrOrgSim=ORG_DEPARTMENTS.map(d=>{const rate=0.4+Math.random()*0.35;const connected=Math.max(0,Math.round(d.size*rate));const scores=[];for(let i=0;i<connected;i++)scores.push(1+Math.floor(Math.random()*5));return {name:d.name,size:d.size,connected,scores}})}
function bucketCounts(scores){let good=0,mid=0,low=0;scores.forEach(s=>{if(s>=4)good++;else if(s===3)mid++;else low++});const total=scores.length||1;return {good,mid,low,total,goodPct:Math.round(good/total*100),midPct:Math.round(mid/total*100),lowPct:Math.round(low/total*100)}}
function myRecentScores(days=7){const now=new Date();const out=[];for(let i=0;i<days;i++){const d=new Date(now);d.setDate(d.getDate()-i);const key=dkey(d.getFullYear(),d.getMonth(),d.getDate());const e=state.diary[key];if(e&&e.mood)out.push(e.mood.score)}return out}
function orgAnonSummaryPreview(){const scores=myRecentScores(7);const checkins=scores.length;const avg=checkins?scores.reduce((a,b)=>a+b,0)/checkins:null;const avgLabel=avg===null?'ยังไม่มีข้อมูล':avg>=4?'ส่วนใหญ่ดี':avg>=3?'ปานกลาง':'ควรดูแลเพิ่ม';return {checkins,days:7,avgLabel}}
function regenHrSim(size){const members=[];for(let i=0;i<Math.max(0,size-1);i++)members.push(1+Math.floor(Math.random()*5));state.hrSimMembers=members;state.hrSimTeamSize=size}
const CRISIS_PATTERN=/ฆ่าตัวตาย|อยากตาย|ไม่อยากมีชีวิตอยู่|ทำร้ายตัวเอง|จบชีวิตตัวเอง|หายไปจากโลกนี้/;
function containsCrisisSignal(text){return CRISIS_PATTERN.test(String(text||''))}
function dkey(y,m,d){return `${y}-${String(m+1).padStart(2,'0')}-${String(d).padStart(2,'0')}`}
function nextDayKey(key){const d=new Date(key+'T12:00:00');d.setDate(d.getDate()+1);return dkey(d.getFullYear(),d.getMonth(),d.getDate())}
function latestPlan(){return Object.values(state.diary).filter(e=>e&&e.plan).sort((a,b)=>b.date.localeCompare(a.date))[0]||null}
function closeoutStreak(){let streak=0,d=new Date();while(true){const key=dkey(d.getFullYear(),d.getMonth(),d.getDate());const e=state.diary[key];if(e&&e.plan){streak++;d.setDate(d.getDate()-1)}else break}return streak}
function renderInto(id,htmlStr){const el=document.getElementById(id);if(el)el.innerHTML=htmlStr}
function persist(){localStorage.setItem(SKEY,JSON.stringify({demoPosts:state.demoPosts,communityTokens:state.communityTokens,diary:state.diary,released:state.released,org:state.org,purchased:state.purchased}));}
function html(s){return String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));}
function fmtDate(value){try{return new Date(value).toLocaleDateString('th-TH',{day:'numeric',month:'short',year:'numeric'})}catch{return ''}}
function today(){let d=new Date();return [d.getFullYear(),String(d.getMonth()+1).padStart(2,'0'),String(d.getDate()).padStart(2,'0')].join('-')}
function tomorrow(){const d=new Date();d.setDate(d.getDate()+1);return [d.getFullYear(),String(d.getMonth()+1).padStart(2,'0'),String(d.getDate()).padStart(2,'0')].join('-')}
function toast(s){const el=document.getElementById('toast');el.textContent=s;el.classList.add('show');clearTimeout(toast.t);toast.t=setTimeout(()=>el.classList.remove('show'),4000)}
function link(url,label,klass='btn secondary'){return `<a class="${klass}" target="_blank" rel="noopener noreferrer" href="${html(url)}">${html(label)} ↗</a>`}
function header(kicker,title,desc){return `<div class="page-kicker">${kicker}</div><h1 class="page-title">${title}</h1><p class="page-subtitle">${desc}</p>`}
function quick(icon,title,desc,page,tab=''){return `<article class="quick-card"><span class="card-icon">${icon}</span><b>${title}</b><p>${desc}</p><button data-page="${page}"${tab?` data-tab="${tab}"`:''}>เริ่มใช้งาน →</button></article>`}
function renderNav(){const desktop=document.getElementById('desktop-nav'),mobile=document.getElementById('mobile-nav');if((!state.purchased&&!state.org)||state.hrLoggedIn){desktop.innerHTML='';mobile.innerHTML='';return}desktop.innerHTML=NAV.map(([key,ic,title])=>`<button class="nav-item ${state.page===key?'active':''}" data-page="${key}" ${state.page===key?'aria-current="page"':''}><span class="nav-icon">${ic}</span>${title}</button>`).join('');const m=['home','diary','community','checkin','help'];mobile.innerHTML=NAV.filter(([id])=>m.includes(id)).map(([key,ic,title])=>`<button data-page="${key}" class="${state.page===key?'active':''}" ${state.page===key?'aria-current="page"':''}><span class="nicon">${ic}</span>${key==='diary'?'ไดอารี่':key==='community'?'ปล่อยใจ':key==='checkin'?'เช็กใจ':key==='help'?'ช่วยเหลือ':'หน้าแรก'}</button>`).join('')}
function diaryTrendBars(){const recent=Object.values(state.diary).filter(e=>e&&e.date&&e.mood).sort((a,b)=>a.date.localeCompare(b.date)).slice(-7);return recent.length?`<div class="mood-bars-wrap"><div class="mood-bars">${recent.map(e=>`<div class="mood-bar" title="${html(fmtDate(e.date))}: ${html(e.mood.label)}" data-label="${html(new Date(e.date+'T12:00:00').toLocaleDateString('th-TH',{day:'numeric',month:'short'}))}" data-low="${e.mood.score<=2}" style="height:${Math.max(10,e.mood.score*18)}%"></div>`).join('')}</div></div><div class="helper">อิงจากอารมณ์ 5 ระดับที่คุณเลือกในแต่ละวัน ยิ่งแท่งต่ำยิ่งหมายถึงวันที่หนักกว่าปกติ ไม่ใช่ผลตรวจทางการแพทย์</div>`:`<div class="empty">ยังไม่มีข้อมูล ลองเช็กใจวันนี้เพื่อเริ่มดูแนวโน้ม</div>`}
function todayMoodWidget(){const e=state.diary[today()];if(e&&e.mood)return `<div class="panel" style="display:flex;align-items:center;gap:14px;margin-bottom:20px;flex-wrap:wrap"><span style="font-size:28px">${e.mood.emoji}</span><div><b>วันนี้คุณบันทึกว่า "${html(e.mood.label)}"</b><p class="helper" style="margin:3px 0 0">แก้ไขหรือเขียนเพิ่มได้ที่หน้าไดอารี่</p></div><button class="btn small secondary" data-page="diary" style="margin-left:auto">เปิดไดอารี่ →</button></div>`;return `<div class="panel" style="display:flex;align-items:center;gap:14px;margin-bottom:20px;flex-wrap:wrap"><span style="font-size:28px">🙂</span><div><b>วันนี้ยังไม่ได้บันทึกไดอารี่</b><p class="helper" style="margin:3px 0 0">ใช้เวลาสักนิดเพื่อเช็กความรู้สึกของวันนี้</p></div><button class="btn small secondary" data-page="diary" style="margin-left:auto">เขียนตอนนี้ →</button></div>`}
function renderHome(){const latest=latestPlan();return `<section class="hero"><span class="pill">🌿 พื้นที่พักใจสำหรับคนทำงาน</span><h1>จบวันทำงานแล้ว<br>ให้ใจได้พักบ้าง</h1><p>ไม่จำเป็นต้องเข้มแข็งตลอดเวลา JOBWAN ช่วยคุณจัดการเรื่องค้างใจ มีพื้นที่รับฟัง และค้นหาความช่วยเหลือเมื่อจำเป็น</p><div class="btn-row"><button class="btn" data-action="start-shutdown-wizard">☾ เริ่มปิดวันทำงาน</button><button class="btn secondary" data-page="community">♡ ไปพื้นที่ปล่อยใจ</button></div></section>
  ${state.org?`<div class="alert" style="margin-bottom:16px">🏢 เชื่อมต่อกับองค์กร ${html(state.org.code)} · ข้อมูลส่วนตัวของคุณยังอยู่ในเครื่องนี้เท่านั้น องค์กรเห็นแค่ภาพรวมแบบไม่ระบุตัวตน</div>`:''}
  ${todayMoodWidget()}
  <div class="section-heading"><h2>วันนี้อยากดูแลใจแบบไหน?</h2><span class="chip">เริ่มได้ฟรี</span></div><section class="grid-3">${quick('📖','ไดอารี่ & จบวันทำงาน','เขียนอิสระ หรือใช้วิซาร์ดปิดวันทำงานแบบมีขั้นตอน','diary')}${quick('💬','ระบายความรู้สึก','โพสต์หรือส่งกำลังใจโดยใช้ชื่อสมมติ','community','public')}${quick('🧭','เช็กใจวันนี้','เลือกอารมณ์ของวันนี้ และไปยังแบบประเมินมาตรฐาน','checkin')}${quick('🏥','ค้นหาความช่วยเหลือ','หาสถานพยาบาลและข้อมูลผู้เชี่ยวชาญ','help')}${quick('🕊','ปล่อยวางส่วนตัว','เขียนสิ่งที่อยากปล่อย แล้วเลือกวิธีทิ้งมันไว้ตรงนี้ ไม่มีใครเห็น','community','private')}${quick('📰','อ่านแล้วใจเบา','บทความสั้น ๆ ที่นำไปใช้ในชีวิตจริง','articles')}${quick('🔒','ข้อมูลอยู่กับคุณ','ลบข้อมูลที่บันทึกในอุปกรณ์ได้ทุกเมื่อ','settings')}</section>
  <div class="section-heading"><h2>ภาพรวมของฉัน</h2><button class="btn small secondary" data-page="checkin">เช็กใจ +</button></div><div class="grid-2"><div class="panel"><div class="eyebrow">บันทึกอารมณ์ช่วงที่ผ่านมา</div><h2>แนวโน้ม 7 วันล่าสุด</h2>${diaryTrendBars()}</div><div class="panel"><div class="eyebrow">สิ่งที่ค้างใจล่าสุด</div><h2>แผนที่คุณฝากไว้</h2>${latest?`<p class="small-text"><b>${html(latest.pending||'')}</b></p><p class="muted small-text">${html(latest.plan)}</p>${latest.win?`<p class="helper">✦ วันนั้นทำสำเร็จ: ${html(latest.win)}</p>`:''}<p class="helper">${fmtDate(latest.planWhen)} เวลา ${html(latest.planReminder)} น.</p>`:`<div class="empty">ยังไม่มีบันทึก<br>เริ่มต้นด้วยการเขียนเรื่องที่ค้างอยู่ในใจ</div>`}<div style="margin-top:16px"><button class="btn secondary small" data-action="start-shutdown-wizard">เปิดบันทึก →</button></div></div></div>
  <div class="panel" style="margin-top:20px">${renderMindSignal()}</div>`}
function shutdownWizardPanel(){
  const todayEntry=state.diary[today()]||{};
  const exitLink=`<div class="split" style="margin-bottom:14px"><span class="eyebrow">โหมดพิธีกรรมปิดวันทำงาน</span><button type="button" class="btn small secondary" data-action="diary-exit-wizard">← กลับไปบันทึกแบบเต็ม</button></div>`;
  if(state.step===3){
    const streak=closeoutStreak();
    const streakLine=streak<=1?'✨ เริ่มต้นดูแลใจวันนี้แล้ว':`🔥 ปิดวันทำงานต่อเนื่องมาแล้ว ${streak} วัน`;
    return `${exitLink}<div class="center feature-highlight step-pop" style="border-radius:14px;padding:22px"><div class="big-icon">🌙</div><h2>วันนี้จบงานแล้ว</h2><p class="small-text">สิ่งที่ค้างอยู่มีแผนแล้ว วันนี้คุณสามารถเลือกใช้เวลาไปกับการพักผ่อนได้</p><div class="streak-chip">${streakLine}</div>${todayEntry.win?`<div class="alert" style="margin-top:14px">✦ สิ่งที่วันนี้ทำสำเร็จ: <b>${html(todayEntry.win)}</b></div>`:''}<div class="alert">บันทึกไว้บนอุปกรณ์นี้เท่านั้น หากเปิดใช้งานด้วยเบราว์เซอร์อื่น ข้อมูลจะไม่ซิงค์กัน</div><div style="margin-top:20px"><button class="btn" data-action="restart-shutdown">แก้ไขอีกครั้ง</button></div></div>`;
  }
  const dots=[0,1,2].map(i=>`<span class="step-dot ${state.step>=i?'on':''}"></span>`).join('');
  let body;
  if(state.step===0){
    const val=state.draft!==undefined?state.draft:(todayEntry.pending||'');
    body=`<div class="eyebrow">ขั้นตอนที่ 1 / 3</div><h2>วันนี้มีอะไรค้างใจ?</h2><p class="panel-desc">เขียนเรื่องเดียวที่กังวลมากที่สุด ไม่ต้องจัดการให้เสร็จตอนนี้ ถ้าเคยเขียนไว้ในไดอารี่ของวันนี้แล้วจะดึงมาให้อัตโนมัติ</p><div class="field"><label for="task">เรื่องที่ค้างอยู่ในใจ</label><textarea id="task" name="task" required maxlength="500" placeholder="เช่น พรุ่งนี้ต้องส่งรายงานแต่ยังไม่เริ่มเลย">${html(val)}</textarea></div><button class="btn" type="submit">ถัดไป →</button>`;
  }else if(state.step===1){
    const val=state.winDraft!==undefined?state.winDraft:(todayEntry.win||'');
    body=`<div class="eyebrow">ขั้นตอนที่ 2 / 3</div><h2>วันนี้มีอะไรทำสำเร็จ หรือรู้สึกดีบ้าง?</h2><p class="panel-desc">เรื่องเล็กแค่ไหนก็นับ เช่น ตอบอีเมลที่ค้างไว้ หรือแค่ได้ลุกไปเดินเล่นพักสมอง ไม่บังคับตอบ</p><div class="field"><label for="win">สิ่งที่ทำสำเร็จวันนี้ (ไม่บังคับ)</label><textarea id="win" name="win" maxlength="300" placeholder="เช่น ได้พักกินข้าวเที่ยงแบบไม่รีบ">${html(val)}</textarea></div><div class="btn-row"><button type="button" class="btn secondary" data-action="shutdown-back">← กลับ</button><button class="btn" type="submit">ถัดไป →</button></div>`;
  }else{
    body=`<div class="eyebrow">ขั้นตอนที่ 3 / 3</div><h2>พรุ่งนี้จะเริ่มตรงไหน?</h2><p class="panel-desc">เลือกขั้นตอนแรกที่ทำได้จริง เพื่อให้ความคิดได้พัก</p><div class="alert" style="margin-bottom:18px">เรื่องที่บันทึก: <b>${html(state.draft||'')}</b></div><div class="field"><label for="plan">ขั้นตอนแรกที่คุณจะทำ</label><input class="input" name="plan" id="plan" maxlength="500" required value="${html(todayEntry.plan||'')}" placeholder="เช่น เปิดไฟล์แล้วเริ่มร่าง 15 นาที"></div><div class="field"><label for="reminder">เวลาที่อยากกลับมาทบทวนวันพรุ่งนี้</label><input class="input" id="reminder" name="reminder" type="time" value="${html(todayEntry.planReminder||'09:00')}" required></div><div class="btn-row"><button type="button" class="btn secondary" data-action="shutdown-back">← กลับ</button><button class="btn" type="submit">☾ จบงานวันนี้</button></div>`;
  }
  return `${exitLink}<div class="step-pop"><div class="steps">${dots}</div><form id="shutdown-form">${body}</form></div>`;
}

function moodPickHtml(name,current){return `<div class="mood-pick">${MOODS.map(m=>`<label class="mood-pick-opt${current===m.score?' selected':''}"><input type="radio" name="${name}" value="${m.score}" ${current===m.score?'checked':''}><span class="mpe">${m.emoji}</span><span class="mpl">${m.label}</span></label>`).join('')}</div>`}
function renderDiaryCalendar(){
  const y=state.calYear,m=state.calMonth;
  const first=new Date(y,m,1),daysInMonth=new Date(y,m+1,0).getDate();
  const monthLabel=first.toLocaleDateString('th-TH',{month:'long',year:'numeric'});
  let cells='';
  for(let i=0;i<first.getDay();i++)cells+='<div></div>';
  for(let d=1;d<=daysInMonth;d++){
    const key=dkey(y,m,d);
    const e=state.diary[key];
    let cls='cal-day';
    if(e){cls+=' has';if(e.mood){if(e.mood.score>=4)cls+=' good';else if(e.mood.score===3)cls+=' mid';else cls+=' low'}}
    if(key===state.selectedDiaryDate)cls+=' selected';
    cells+=`<button type="button" class="${cls}" data-action="diary-pick-day" data-date="${key}" aria-label="${html(fmtDate(key))}${e&&e.mood?' · '+html(e.mood.label):''}"><b>${d}</b>${e&&e.mood?`<small>${e.mood.emoji}</small>`:''}</button>`;
  }
  return `<div class="cal-head"><button type="button" class="btn small secondary" data-action="diary-prev-month">‹</button><b>${html(monthLabel)}</b><button type="button" class="btn small secondary" data-action="diary-next-month">›</button></div><div class="cal-week"><span>อา</span><span>จ</span><span>อ</span><span>พ</span><span>พฤ</span><span>ศ</span><span>ส</span></div><div class="cal-grid">${cells}</div>`;
}
function renderDiaryEntryForm(){
  const key=state.selectedDiaryDate,e=state.diary[key]||{};
  return `<div class="split"><div><div class="eyebrow">DAILY ENTRY</div><h2>${html(fmtDate(key))}</h2></div>${state.diary[key]?`<button type="button" class="btn small warning" data-action="diary-delete">ลบบันทึก</button>`:''}</div>
  <form id="diary-form">
    <div class="field"><label>วันนี้รู้สึกอย่างไร?</label>${moodPickHtml('mood',e.mood?e.mood.score:null)}</div>
    <div class="field"><label for="d-story">วันนี้เกิดอะไรขึ้น?</label><textarea id="d-story" name="story" class="textarea" maxlength="1500" placeholder="วันนี้เป็นยังไงบ้าง...">${html(e.story||'')}</textarea></div>
    <div class="field"><label for="d-win">สิ่งที่ภูมิใจหรือทำสำเร็จ</label><textarea id="d-win" name="win" class="textarea" maxlength="500" placeholder="เรื่องเล็ก ๆ ก็เขียนได้">${html(e.win||'')}</textarea></div>
    <div class="field"><label for="d-pending">เรื่องที่ยังค้างใจ</label><textarea id="d-pending" name="pending" class="textarea" maxlength="500" placeholder="มีอะไรที่ยังวนอยู่ในหัวไหม">${html(e.pending||'')}</textarea></div>
    <div class="field"><label for="d-good">สิ่งดี ๆ ที่อยากเก็บไว้ใน Memory Jar</label><textarea id="d-good" name="good" class="textarea" maxlength="300" placeholder="เช่น เพื่อนซื้อกาแฟให้ / ได้กลับบ้านตรงเวลา">${html(e.good||'')}</textarea></div>
    <div class="field"><label for="d-self">ข้อความถึงตัวเอง</label><textarea id="d-self" name="selfNote" class="textarea" maxlength="300" placeholder="อยากบอกอะไรกับตัวเองวันนี้">${html(e.selfNote||'')}</textarea></div>
    <div class="field"><label for="d-plan">แผนเริ่มต้นสำหรับวันถัดไป (ไม่บังคับ)</label><input class="input" id="d-plan" name="plan" maxlength="500" value="${html(e.plan||'')}" placeholder="เช่น เปิดไฟล์แล้วเริ่มร่าง 15 นาที"></div>
    <div class="field"><label for="d-plan-reminder">เวลาที่อยากกลับมาทบทวน</label><input class="input" id="d-plan-reminder" name="planReminder" type="time" value="${html(e.planReminder||'09:00')}"></div>
    <button class="btn" type="submit">💾 บันทึก</button>
  </form>`;
}
function diaryWords(text){const ignore=['วันนี้','พรุ่งนี้','แล้ว','มาก','ที่','และ','เรื่อง','อยาก','ยัง','ไม่','ได้','มี','ของ','ไป','มา','ก็','ให้','กับ','จาก','คือ','งาน'];return (text||'').replace(/[^\u0E00-\u0E7Fa-zA-Z0-9\s]/g,' ').split(/\s+/).filter(w=>w.length>2&&!ignore.includes(w))}
function diaryInRange(key,range){const d=new Date(key+'T12:00:00'),n=new Date(),diff=(n-d)/86400000;if(range==='week')return diff>=0&&diff<7;if(range==='month')return d.getFullYear()===n.getFullYear()&&d.getMonth()===n.getMonth();return d.getFullYear()===n.getFullYear()}
function renderDiaryReport(){
  const range=state.diaryReportRange;
  const all=Object.values(state.diary).filter(e=>e&&e.date);
  const arr=all.filter(e=>diaryInRange(e.date,range));
  const counts={};MOODS.forEach(m=>counts[m.label]=0);
  arr.filter(e=>e.mood).forEach(e=>counts[e.mood.label]++);
  const total=Object.values(counts).reduce((a,b)=>a+b,0)||1;
  const bars=MOODS.map(m=>{const c=counts[m.label],p=Math.round(c/total*100);return `<div class="barrow"><span>${m.emoji} ${m.label}</span><div class="bartrack"><div class="barfill" style="width:${p}%"></div></div><b>${c}</b></div>`}).join('');
  const freq={};arr.forEach(e=>diaryWords([e.story,e.win,e.pending].join(' ')).forEach(w=>freq[w]=(freq[w]||0)+1));
  const top=Object.entries(freq).sort((a,b)=>b[1]-a[1]).slice(0,6);
  const topicHtml=top.length?top.map(([w,c])=>`<span class="chip">${html(w)} · ${c}</span>`).join(' '):'<span class="helper">ยังไม่มีข้อมูลพอ</span>';
  const ms=arr.filter(e=>e.mood).map(e=>e.mood.score);
  let insight='ยังไม่มีข้อมูลพอ ลองบันทึกต่อเนื่องอีกสักระยะ';
  if(ms.length>=3){const avg=ms.reduce((a,b)=>a+b,0)/ms.length,low=ms.filter(x=>x<=2).length;if(avg>=4)insight='ช่วงนี้มีวันที่บันทึกว่าโอเคหรือดีค่อนข้างมาก ลองสังเกตว่ามีอะไรช่วยให้วันเหล่านั้นเกิดขึ้น';else if(low>=Math.ceil(ms.length/2))insight='ช่วงนี้คุณบันทึกว่าเครียด/ไม่ไหวค่อนข้างบ่อย นี่ไม่ใช่การวินิจฉัย แต่ลองพัก พูดคุยกับคนที่ไว้ใจ หรือพิจารณาความช่วยเหลือจากผู้เชี่ยวชาญหากต่อเนื่อง';else insight='ช่วงนี้มีทั้งวันที่โอเคและวันที่เหนื่อยปะปนกัน ลองดูหัวข้อที่เกิดซ้ำเพื่อเข้าใจรูปแบบของตัวเอง'}
  const y=new Date().getFullYear();
  const yearArr=all.filter(e=>new Date(e.date+'T12:00:00').getFullYear()===y);
  const yearMoods=yearArr.filter(e=>e.mood);
  let bestMonth='-',heavyMonth='-';
  if(yearMoods.length){const pm={};yearMoods.forEach(e=>{const mo=new Date(e.date+'T12:00:00').getMonth();(pm[mo]=pm[mo]||[]).push(e.mood.score)});const av=Object.entries(pm).map(([mo,v])=>[+mo,v.reduce((a,b)=>a+b,0)/v.length]);const sorted=[...av].sort((a,b)=>b[1]-a[1]);bestMonth=new Date(y,sorted[0][0],1).toLocaleDateString('th-TH',{month:'long'});heavyMonth=new Date(y,sorted[sorted.length-1][0],1).toLocaleDateString('th-TH',{month:'long'})}
  const releasedThisYear=state.released.filter(x=>new Date(x.date+'T12:00:00').getFullYear()===y).length;
  return `<div class="split"><h3 style="margin:0">ภาพรวมอารมณ์</h3><div class="room-filters" style="margin:0">${['week','month','year'].map(r=>`<button type="button" class="chip-filter ${range===r?'active':''}" data-action="diary-report-range" data-range="${r}">${r==='week'?'สัปดาห์':r==='month'?'เดือน':'ปี'}</button>`).join('')}</div></div>
  <div style="margin:14px 0">${bars}</div>
  <div class="eyebrow" style="margin-top:10px">สิ่งที่ปรากฏบ่อย</div><div style="margin:8px 0 14px">${topicHtml}</div>
  <div class="alert">${html(insight)}</div>
  <div class="line"></div>
  <div class="eyebrow">MY YEAR IN MIND</div>
  <div class="year-stats"><div><b>${yearArr.length}</b><span>วันที่บันทึก</span></div><div><b>${bestMonth}</b><span>เดือนที่ใจเบาที่สุด</span></div><div><b>${heavyMonth}</b><span>เดือนที่หนักที่สุด</span></div><div><b>${releasedThisYear}</b><span>เรื่องที่ปล่อยไป</span></div></div>`;
}
function renderMindSignal(){
  const recent=Object.values(state.diary).filter(e=>e&&e.date&&e.mood).filter(e=>{const d=(new Date()-new Date(e.date+'T12:00:00'))/86400000;return d>=0&&d<14});
  const head='<h2>ช่วงนี้ควรใส่ใจตัวเองเพิ่มไหม?</h2>';
  if(recent.length<4)return `${head}<div class="signal"><span class="sig green"></span><div><b>ยังไม่มีข้อมูลเพียงพอ</b><p class="helper">บันทึกไดอารี่ต่อเนื่องอีกสักระยะเพื่อให้เห็นแนวโน้ม</p></div></div>`;
  const low=recent.filter(e=>e.mood.score<=2).length,ratio=low/recent.length;
  if(ratio>=.6)return `${head}<div class="signal"><span class="sig orange"></span><div><b>ช่วงนี้มีหลายวันที่ควรใส่ใจ</b><p class="helper">คุณบันทึกว่าเครียด/ไม่ไหวค่อนข้างบ่อยใน 14 วันที่ผ่านมา หากต่อเนื่องหรือกระทบชีวิตประจำวัน ลองคุยกับคนที่ไว้ใจหรือผู้เชี่ยวชาญ</p></div></div>`;
  if(ratio>=.3)return `${head}<div class="signal"><span class="sig yellow"></span><div><b>ช่วงนี้ลองดูแลตัวเองเพิ่มอีกนิด</b><p class="helper">มีบางวันที่ใจหนักกว่าปกติ ลองจัดเวลาพักให้ตัวเอง</p></div></div>`;
  return `${head}<div class="signal"><span class="sig green"></span><div><b>แนวโน้มช่วงนี้ค่อนข้างคงที่</b><p class="helper">บันทึกต่อไปเพื่อเห็นรูปแบบชัดขึ้น</p></div></div>`;
}
