function renderCommunityStoriesBody(){const allPosts=state.online?state.posts:[...state.demoPosts,...publicSamples];const posts=state.communityFilter==='all'?allPosts:allPosts.filter(p=>(p.category||'เรื่องทั่วไป')===state.communityFilter);const roomChips=COMMUNITY_ROOMS.map(r=>`<button class="chip-filter ${state.communityFilter===r?'active':''}" data-action="filter-room" data-room="${html(r)}">${r==='all'?'ทั้งหมด':html(r)}</button>`).join('');return `<p class="panel-desc">${state.online?'แสดงเฉพาะโพสต์ที่ผู้ดูแลอนุมัติแล้ว':'ข้อความด้านล่างเป็นตัวอย่างเพื่อสาธิตหน้าจอ ไม่ใช่โพสต์จากคนจริง'}</p><div class="room-filters">${roomChips}</div><div class="stack">${posts.length?posts.map(p=>postHtml(p,!state.online)).join(''):'<div class="empty">ยังไม่มีโพสต์ในห้องนี้</div>'}</div>`}
function renderCommunityPublicBody(){const mode=state.online?'ชุมชนทดลอง (ต้องผ่านผู้ดูแลก่อนเผยแพร่)':'โหมดสาธิตในเครื่อง — ยังไม่เชื่อมกับผู้ใช้อื่น';const prefill=state.prefillPostBody||'';state.prefillPostBody=null;return `<div class="alert warn" style="margin-bottom:20px"><b>พื้นที่สำหรับผู้มีอายุ 18 ปีขึ้นไป</b> · การโพสต์และตอบกลับจะเปิดเผยต่อผู้ใช้ในชุมชนเมื่อผู้ดูแลอนุมัติ ไม่ใช่พื้นที่ฉุกเฉินหรือบริการให้คำปรึกษาจากผู้เชี่ยวชาญ ห้ามใส่ชื่อจริง เบอร์โทร ที่อยู่ หรือข้อมูลผู้ป่วย/ลูกค้า หากกำลังไม่ปลอดภัย โทร 1323 หรือ 1669</div>
 <div class="grid-2"><section class="stack"><div class="panel"><div class="split"><h2>แบ่งปันเรื่องราวของคุณ</h2><span class="chip">${mode}</span></div><p class="panel-desc">ใช้ชื่อสมมติได้ และสามารถโพสต์สั้น ๆ โดยไม่ต้องเล่ารายละเอียดที่ระบุตัวบุคคล</p><form id="post-form"><div class="field"><label for="alias">ชื่อสมมติ</label><input class="input" id="alias" name="alias" maxlength="30" required placeholder="เช่น คนชอบชาเขียว"></div><div class="field"><label for="category">อยากเล่าเรื่องอะไร?</label><select class="select" id="category" name="category"><option>เรื่องงาน</option><option>ความสัมพันธ์</option><option>กำลังใจ</option><option>เรื่องทั่วไป</option></select></div><div class="field"><label for="post-body">ข้อความที่อยากระบาย</label><textarea class="textarea" id="post-body" name="body" minlength="5" maxlength="1200" required placeholder="วันนี้อยากบอกว่า...">${html(prefill)}</textarea></div><label class="checkrow"><input type="checkbox" name="adult" required>ฉันมีอายุ 18 ปีขึ้นไป</label><label class="checkrow" style="margin:10px 0 16px"><input type="checkbox" name="rules" required>ยอมรับกติกาชุมชน ไม่ระบุข้อมูลส่วนตัว ไม่คุกคาม ไม่ให้คำแนะนำรักษาโรคแทนผู้เชี่ยวชาญ</label><button class="btn" type="submit">${state.online?'ส่งให้ผู้ดูแลตรวจข้อความ':'ทดลองบันทึกโพสต์ในเครื่อง'}</button></form></div><div class="panel"><h2>กติกาที่ช่วยให้พื้นที่ปลอดภัยขึ้น</h2><p class="small-text">✓ รับฟังโดยไม่ตัดสิน<br>✓ เคารพความเป็นส่วนตัวของกันและกัน<br>✓ ไม่แชร์ข้อมูลติดต่อหรือชักชวนไปแชตส่วนตัว<br>✓ กดรายงานข้อความไม่เหมาะสม<br>✓ ถ้าต้องการความช่วยเหลือเร่งด่วน ให้ติดต่อบริการวิชาชีพโดยตรง</p><a href="tel:1323" class="btn small secondary">โทรสายด่วนสุขภาพจิต 1323</a></div></section>
 <section class="stack"><div class="panel"><div class="split"><h2>เรื่องราวจากชุมชน</h2>${state.online?'<button class="btn small secondary" data-action="reload-posts">รีเฟรช</button>':''}</div><div id="community-stories-body">${renderCommunityStoriesBody()}</div></div></section></div>`}
