 <div class="room-filters" style="margin-bottom:20px"><button class="chip-filter ${tab==='public'?'active':''}" data-action="community-tab" data-tab="public">🫂 แบ่งปันกับชุมชน</button><button class="chip-filter ${tab==='private'?'active':''}" data-action="community-tab" data-tab="private">🕊 ปล่อยส่วนตัว</button></div>
