document.addEventListener('submit',async e=>{const f=e.target;if(!['shutdown-form','quick-mood-form','post-form','diary-form','org-join-form','hr-login-form','org-paywall-join-form','hr-entry-login-form'].includes(f.id))return;e.preventDefault();if(f.id==='hr-entry-login-form'){const d=new FormData(f),orgCode=String(d.get('orgCode')||'').trim(),email=String(d.get('email')||'').trim(),password=String(d.get('password')||'');if(!orgCode||!email||!password)return toast('กรอกข้อมูลให้ครบก่อนนะ');if(!state.org){state.org={code:orgCode,joinedAt:new Date().toISOString()};state.hrOnlySession=true}state.hrLoggedIn=true;state.hrAdminEmail=email;persist();if(state.hrSimTeamSize===undefined)regenHrSim(3);render();toast('เข้าสู่ระบบ HR แล้ว (จำลอง)');return}if(f.id==='org-paywall-join-form'){const d=new FormData(f),code=String(d.get('code')||'').trim();if(!code)return toast('กรอกรหัสองค์กรก่อนนะ');state.org={code,joinedAt:new Date().toISOString()};persist();render();toast('เข้าร่วมองค์กรแล้ว (โหมดสาธิต) — ใช้งานฟรีผ่านองค์กร');return}if(f.id==='hr-login-form'){const d=new FormData(f),email=String(d.get('email')||'').trim(),password=String(d.get('password')||'');if(!email||!password)return toast('กรอกอีเมลและรหัสผ่านก่อนนะ');state.hrLoggedIn=true;state.hrAdminEmail=email;if(state.hrSimTeamSize===undefined)regenHrSim(3);render();toast('เข้าสู่ระบบ HR แล้ว (จำลอง)');return}if(f.id==='org-join-form'){const d=new FormData(f),code=String(d.get('code')||'').trim();if(!code)return toast('กรอกรหัสองค์กรก่อนนะ');state.org={code,joinedAt:new Date().toISOString()};persist();render();toast('เชื่อมต่อองค์กรแล้ว (โหมดสาธิต)');return}if(f.id==='post-form')return sendPost(f);if(f.id==='quick-mood-form'){const d=new FormData(f),key=today(),scoreRaw=d.get('mood'),moodObj=scoreRaw?MOODS.find(m=>String(m.score)===String(scoreRaw))||null:null;if(!moodObj)return toast('เลือกอารมณ์ก่อนนะ');const note=String(d.get('note')||'').trim(),entry=state.diary[key]||{date:key};entry.date=key;entry.mood=moodObj;if(note)entry.story=(entry.story?entry.story+'\n':'')+note;entry.updatedAt=new Date().toISOString();state.diary[key]=entry;persist();if(containsCrisisSignal(note))showCrisisSupport();render();toast('บันทึกเช็กใจแล้ว 💗');return}if(f.id==='diary-form'){const d=new FormData(f),key=state.selectedDiaryDate,scoreRaw=d.get('mood'),moodObj=scoreRaw?MOODS.find(m=>String(m.score)===String(scoreRaw))||null:null,entry=state.diary[key]||{date:key};entry.date=key;entry.mood=moodObj||entry.mood||null;entry.story=String(d.get('story')||'').trim();entry.win=String(d.get('win')||'').trim();entry.pending=String(d.get('pending')||'').trim();entry.good=String(d.get('good')||'').trim();entry.selfNote=String(d.get('selfNote')||'').trim();const plan=String(d.get('plan')||'').trim(),planReminder=String(d.get('planReminder')||'09:00');if(plan){if(entry.plan!==plan||entry.planReminder!==planReminder)entry.notified=false;entry.plan=plan;entry.planReminder=planReminder;entry.planWhen=nextDayKey(key)}else{delete entry.plan;delete entry.planReminder;delete entry.planWhen;delete entry.notified}entry.updatedAt=new Date().toISOString();state.diary[key]=entry;persist();if(containsCrisisSignal([entry.story,entry.pending,entry.selfNote].join(' ')))showCrisisSupport();render();toast('บันทึกไดอารี่แล้ว 💾');return}if(f.id==='shutdown-form'){const d=new FormData(f);if(state.step===0){state.draft=String(d.get('task')||'').trim();if(!state.draft)return;state.step=1;return render()}if(state.step===1){state.winDraft=String(d.get('win')||'').trim();state.step=2;return render()}const plan=String(d.get('plan')||'').trim(),reminder=String(d.get('reminder')||'09:00');if(!plan)return;const key=today(),entry=state.diary[key]||{date:key};entry.date=key;entry.pending=state.draft;entry.win=state.winDraft||'';entry.plan=plan;entry.planReminder=reminder;entry.planWhen=tomorrow();entry.notified=false;entry.updatedAt=new Date().toISOString();state.diary[key]=entry;persist();if(containsCrisisSignal([entry.pending,entry.win].join(' ')))showCrisisSupport();state.step=3;render();toast('บันทึกแผนสำหรับวันพรุ่งนี้แล้ว')}});
